query:
SELECT DISTINCT ?item ?sl ?uk ?ru ?en WHERE {
  ?item wdt:P171+ wd:Q10908 ; wdt:P105 ?rank . VALUES ?rank { wd:Q7432 wd:Q34740 wd:Q35409 }
  ?item wikibase:sitelinks ?sl . FILTER(?sl >= 3)
  ?item rdfs:label ?uk . FILTER(LANG(?uk) = "uk")
  ?item rdfs:label ?ru . FILTER(LANG(?ru) = "ru")
  OPTIONAL { ?item rdfs:label ?en . FILTER(LANG(?en) = "en") }
} ORDER BY DESC(?sl) LIMIT 3000
